package com.ntando.ivu.data.entity

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Offline queue record for flashcard reviews submitted while offline.
 *
 * Allows multiple review events for the same card to be queued in chronological order
 * and replayed to the backend server in sequence upon reconnection.
 *
 * @property id Primary key auto-generated by Room.
 * @property cardLocalId Room local primary key ID of the reviewed flashcard.
 * @property cardRemoteId Optional server backend ID of the flashcard.
 * @property deckRemoteId Server backend ID of the deck containing the card.
 * @property rating Review rating string ("again", "hard", "good", "easy").
 * @property reviewedAt Timestamp in epoch milliseconds when review was recorded offline.
 * @property ownerUserId Firebase UID string of user who submitted the review.
 */
@Entity(tableName = "pending_reviews")
data class PendingReview(
    /** Auto-generated primary key ID for queue item. */
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    /** Room database local primary key ID of reviewed card. */
    val cardLocalId: Long,
    /** Server remote identifier for flashcard if synchronized. */
    val cardRemoteId: String? = null,
    /** Server remote identifier for parent deck. */
    val deckRemoteId: String,
    /** SM-2 algorithm rating value string ("again", "hard", "good", "easy"). */
    val rating: String,
    /** Epoch timestamp in milliseconds when review was executed. */
    val reviewedAt: Long = System.currentTimeMillis(),
    /** Firebase UID string of user who performed this review. */
    val ownerUserId: String = ""
)
